import bpy,json,math
scene=bpy.data.scenes['TLT_Melee_Authoring'];bpy.context.window.scene=scene
DATA=json.loads(scene['authored_clips']);fps=scene.render.fps
M={'right':'RightShoulder','left':'LeftShoulder','elbow':'RightElbow','leftElbow':'LeftElbow','wrist':'RightWrist','neck':'Neck','torso':'Waist','rightHip':'RightHip','leftHip':'LeftHip','rightKnee':'RightKnee','leftKnee':'LeftKnee','weapon':'WeaponSocket'}
for o in scene.objects:
 if o.type=='MESH':
  for m in o.data.materials:
   if m and not m.use_nodes:
    color=m.diffuse_color[:];m.use_nodes=True;m.node_tree.nodes.get('Principled BSDF').inputs['Base Color'].default_value=color
out={'source':'Blender 5.2.0 LTS / MCP for Blender 2.2.6; native Armature F-curves','fps':fps,'channels':DATA['channels'],'rest':DATA['rest'],'guard':DATA['guard'],'clips':[]}
for c in DATA['clips']:
 rig=bpy.data.objects[c['classId']+'_Rig'];action=bpy.data.actions[c['name']];action.use_fake_user=True;rig.animation_data.action=action
 fc=action.layers[0].strips[0].channelbag(rig.animation_data.action_slot).fcurves
 clip={k:c[k] for k in ['name','classId','combo','windup','active','recovery','hitDelay','duration']};clip['entryUntil']=c['windup']*.45;clip['curves']={};clip['golden']=[]
 for channel,bone in M.items():
  path=rig.pose.bones[bone].path_from_id('rotation_euler');axes=[]
  for axis,sign in [(0,1),(2,1),(1,-1)]:
   f=next(f for f in fc if f.data_path==path and f.array_index==axis);keys=[]
   for k in f.keyframe_points:
    h=k.handle_right if k!=f.keyframe_points[-1] else k.handle_left
    slope=(h.y-k.co.y)/(h.x-k.co.x)*fps
    leftSlope=(k.co.y-k.handle_left.y)/(k.co.x-k.handle_left.x)*fps
    assert abs(slope-leftSlope)<.002,'Contact handles do not share tangent'
    keys.append([round(k.co.x/fps,9),round(math.degrees(k.co.y)*sign,7),round(math.degrees(slope)*sign,7)])
   axes.append(keys)
  clip['curves'][channel]=axes
 for i in range(33):
  age=c['duration']*i/32;values={}
  for channel,bone in M.items():
   path=rig.pose.bones[bone].path_from_id('rotation_euler');values[channel]=[round(math.degrees(next(f for f in fc if f.data_path==path and f.array_index==axis).evaluate(age*fps))*sign,7) for axis,sign in [(0,1),(2,1),(1,-1)]]
  clip['golden'].append({'age':age,'angles':values})
 out['clips'].append(clip)
for cls,name in [('knight','Knight_Forehand'),('dwarf','Dwarf_HeavyCut')]:bpy.data.objects[cls+'_Rig'].animation_data.action=bpy.data.actions[name]
scene.frame_set(13)
print('TLT_CLIPS_JSON '+json.dumps(out))
